+            if ($index -lt 0 -or $index -gt $tasks.Count -or
+                @($tasks | Where-Object { [int]$_.id -eq [int]$record.task.id }).Count -gt 0) {
+                throw 'The undo record does not match the task store.'
+            }
+            for ($taskIndex = 0; $taskIndex -le $tasks.Count; $taskIndex++) {
+                if ($taskIndex -eq $index) {
+                    $restored.Add($record.task)
+                }
+                if ($taskIndex -lt $tasks.Count) {
+                    $restored.Add($tasks[$taskIndex])
+                }
+            }
+        }
+        default {
+            throw 'The undo record is invalid.'
+        }
+    }
+
+    Write-TaskStore -Path $Path -Tasks $restored.ToArray()
+    try {
+        Remove-Item -LiteralPath (Get-TaskUndoPath -Path $Path) -Force
+    }
+    catch {
+        Write-TaskStore -Path $Path -Tasks $tasks
+        throw
+    }
+
+    return [pscustomobject]@{
+        undone = [string]$record.operation
+        taskId = [int]$record.taskId
+    }
 }

